SELECT CASE WHEN m.entry_quality_score >= 85 THEN 'EQ85+' WHEN m.entry_quality_score >= 70 THEN 'EQ70-84' WHEN m.entry_quality_score >= 55 THEN 'EQ55-69' ELSE 'EQ<55' END AS eq_band, CASE WHEN s.risk_reward_ratio < 1 THEN 'RR<1' WHEN s.risk_reward_ratio < 1.25 THEN 'RR1-1.25' ELSE 'RR>=1.25' END AS rr_band, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losses, SUM(p.realized_pnl) AS pnl_sum, SUM(p.status = 'STOPPED') AS stopped FROM paper_position p JOIN trade_signal s ON s.id = p.signal_id JOIN wallet_managed_position m ON m.entry_signal_id = p.signal_id AND m.symbol = p.symbol WHERE p.opened_at BETWEEN '2026-10-10 00:15:21' AND '2026-10-11 10:00:03' AND p.closed_at IS NOT NULL GROUP BY eq_band, rr_band ORDER BY eq_band, rr_band